\section{Datum-generated rectangles and their intersection}

For \(N\in\Nzero\), \(M\ge1\), and \(0<T<T_*\), define the finite rectangle
norm
\begin{equation}
\begin{aligned}
\frakR_{N,M}(u;T)
:={}&\sum_{n=0}^{N}
\norm{\partial_t^n u}_{L^2(0,T;H^{M+1})}^2\\
&+\sum_{n=0}^{N}
\norm{\partial_t^{n+1}u}_{L^2(0,T;H^{M-1})}^2.
\end{aligned}
\label{eq:rectangle-norm}
\end{equation}
The rectangle \(\cR_{N,M}[u_0]\) is the corresponding finite restriction of
the pressure-explicit jet \eqref{eq:mixed-recurrence}.

\begin{theorem}[Datum-generated whole-terminal compatible rectangles]
\label{thm:rectangles}
The datum \(u_0\), parameter \(\nu\), and their one maximal
velocity--pressure history generate, for every finite \((N,M)\), a rectangle
\(\cR_{N,M}[u_0]\) satisfying the whole-terminal estimate
\begin{equation}
\boxed{
\sup_{0<T<T_*}\frakR_{N,M}(u;T)
\le C_{N,M}(u_0,\nu,T_*)<\infty .}
\label{eq:whole-terminal}
\end{equation}
The constant may depend on the finite coordinate \((N,M)\); no uniformity in
all orders is needed.  If \(N'\le N\) and \(M'\le M\), restriction obeys
\begin{equation}
\rho_{N',M'}^{N,M}\!\left(\cR_{N,M}[u_0]\right)
=\cR_{N',M'}[u_0].
\label{eq:compatibility}
\end{equation}
Every shared coordinate is the corresponding derivative of the same history.
\end{theorem}

\begin{proof}[Finite-coordinate realization]
The pressure-explicit adjacent-row theorem supplies, for every finite
\((n,m)\),
\[
 \partial_t^n u\in L^2(0,T_*;H^{m+1}),
 \qquad
 \partial_t^{n+1}u\in L^2(0,T_*;H^{m-1}),
\]
with the datum-generated bound uniform over all truncations \(T<T_*\).  Fix
\((N,M)\).  Adding the finitely many squared row norms gives
\eqref{eq:whole-terminal}.  Recurrences
\eqref{eq:pressure-recurrence}--\eqref{eq:mixed-recurrence} identify every row
with the actual derivatives of \((u,p)\).  Forgetting higher time coordinates
and applying the lower Sobolev embeddings cannot change a shared derivative,
which gives \eqref{eq:compatibility}.
\end{proof}

Compatibility is what permits the finite pieces to become one object.
Define
\begin{equation}
\cI[u_0]:=\varprojlim_{N,M}\cR_{N,M}[u_0].
\label{eq:intersection}
\end{equation}

\begin{proposition}[Projective assembly]
\label{prop:assembly}
The velocity realization of \(\cI[u_0]\) is the same \(u\) in every
coordinate, and
\begin{equation}
u\in\mathscr X(0,T_*):=
\bigcap_{r,m\in\Nzero}H^r(0,T_*;H^m(\R^3)).
\label{eq:mixed-space}
\end{equation}
Its zeroth temporal projection is
\begin{equation}
\pi_0\cI[u_0]
=u\in\Szero(0,T_*):=
\bigcap_{m\in\Nzero}L^2(0,T_*;H^m(\R^3)).
\label{eq:zero-row}
\end{equation}
\end{proposition}

\begin{proof}
Fix \(r,m\in\Nzero\).  Choose \(N\ge r\) and \(M\ge\max\{1,m\}\).
The rectangle estimate places \(\partial_t^n u\) in
\(L^2(0,T_*;H^m)\) for \(0\le n\le r\), so
\(u\in H^r(0,T_*;H^m)\).  Since \((r,m)\) was arbitrary,
\eqref{eq:mixed-space} follows.  Equation \eqref{eq:compatibility} says that
all lower-coordinate representatives agree, giving one inverse-limit element
and the projection \eqref{eq:zero-row}.
\end{proof}

The order is essential: the complete compatible intersection now exists.
The familiar critical and continuation estimates are its projections.

\section{The intersection reaches the terminal time}

\begin{proposition}[Master trace and embedding readout]
\label{prop:master}
For every finite \(r,m\), the intersection gives
\begin{equation}
\partial_t^r u\in C([0,T_*];H^m),
\qquad
M_{r,m}:=\sup_{0\le t\le T_*}
\norm{\partial_t^r u(t)}_{H^m}<\infty.
\label{eq:master-trace}
\end{equation}
If \(k\in\Nzero\), \(2\le p\le\infty\), and
\[
m>k+\frac32-\frac3p,
\]
then for every \(1\le q\le\infty\),
\begin{equation}
\norm{\nabla^k\partial_t^r u}_{L^q(0,T_*;L^p)}
\le C_{k,m,p}\,T_*^{1/q}M_{r,m},
\label{eq:master-embedding}
\end{equation}
where \(T_*^{1/\infty}=1\).
\end{proposition}

\begin{proof}
Choose the coordinate \((r+1,m)\) in \eqref{eq:mixed-space}.  Then
\(\partial_t^r u\in H^1(0,T_*;H^m)\), and the Hilbert-valued
one-dimensional trace theorem gives \eqref{eq:master-trace}.  The spatial
Sobolev embedding gives
\[
\norm{\nabla^k\partial_t^r u(t)}_{L^p}
\le C_{k,m,p}\norm{\partial_t^r u(t)}_{H^m}.
\]
Taking the time norm proves \eqref{eq:master-embedding}.
\end{proof}

There is also a direct endpoint payment contained in the zeroth row alone.
Write the nonlinear term with the Leray projection:
\[
\mathcal B(u,u):=(u\cdot\nabla)u+\nabla p
=\Pdiv(u\otimes u).
\]
For every finite \(m\),
\begin{equation}
\norm{\mathcal B(u,u)}_{H^m}
\le C_m\norm{u}_{H^{m+2}}^2.
\label{eq:nonlinear-estimate}
\end{equation}
By \eqref{eq:zero-row}, the right side is integrable on \((0,T_*)\).
Also \(\Delta u\in L^1(0,T_*;H^m)\), since the interval is finite and
\(u\in L^2(0,T_*;H^{m+2})\).  Equation \eqref{eq:NS} now gives
\begin{equation}
u_t\in L^1(0,T_*;H^m),
\qquad
u\in W^{1,1}(0,T_*;H^m)
\hookrightarrow C([0,T_*];H^m).
\label{eq:W11-endpoint}
\end{equation}
All endpoint values are traces of the same velocity field.  They define one
common endpoint
\begin{equation}
\boxed{
u_*:=u(T_*)\in\bigcap_{m\in\Nzero}H^m(\R^3)=H^\infty(\R^3).}
\label{eq:smooth-endpoint}
\end{equation}

Pressure reaches the endpoint with the velocity.  For every \(n\), the trace
from Proposition~\ref{prop:master} gives
\[
V_n^*:=\lim_{t\uparrow T_*}\partial_t^n u(t)\in H^\infty.
\]
Starting with \(V_0^*=u_*\), set
\begin{align}
Q_n^*
&:=R_iR_j\sum_{a=0}^{n}\binom{n}{a}V_{a,i}^*V_{n-a,j}^*,
\label{eq:endpoint-pressure}\\
V_{n+1}^*
&:=\nu\Delta V_n^*
-\sum_{a=0}^{n}\binom{n}{a}(V_a^*\cdot\nabla)V_{n-a}^*
-\nabla Q_n^*.
\label{eq:endpoint-velocity}
\end{align}
Multiplication, differentiation, and the Riesz transforms are continuous on
the required Sobolev levels.  Passing \(t\uparrow T_*\) through
\eqref{eq:pressure-recurrence}--\eqref{eq:velocity-recurrence} identifies
\eqref{eq:endpoint-pressure}--\eqref{eq:endpoint-velocity} with the actual
left endpoint traces.  Thus
\begin{equation}
\boxed{V_n^*,Q_n^*\in H^\infty\quad\text{for every }n\in\Nzero.}
\label{eq:complete-endpoint-jet}
\end{equation}
The terminal object is the complete pressure-compatible jet of the original
history.

\section{Same-history restart}

Smooth local existence from \(u_*\in H^\infty\) produces a solution on
\([T_*,T_*+\varepsilon)\).  Its right jet is generated by
\eqref{eq:endpoint-pressure}--\eqref{eq:endpoint-velocity}, so it agrees with
the left jet in \eqref{eq:complete-endpoint-jet}.  Local uniqueness on the
overlap glues the restart to the original history.  The resulting smooth
solution extends past \(T_*\), contradicting finite maximality.  Hence
\begin{equation}
\boxed{T_*=\infty.}
\label{eq:global-time}
\end{equation}
Pressure is recovered from \eqref{eq:pressure} at every time, and the mixed
recurrence propagates all space--time derivatives.  This proves
Theorem~\ref{thm:global}.

The proof has now completed the chain in its original order:
\begin{equation}
\boxed{\begin{gathered}
u_0\longrightarrow \{\cR_{N,M}[u_0]\}_{N,M}
\longrightarrow \cI[u_0]
\longrightarrow u_*\in H^\infty\\
\longrightarrow \text{pressure-complete endpoint jet}
\longrightarrow \text{same-history restart}
\longrightarrow T_*=\infty .
\end{gathered}}
\label{eq:closing-chain}
\end{equation}

\section{Classical estimates as coordinate projections}

The closure above does not require a separate continuation criterion.  Once
\(\cI[u_0]\) is available, each fixed-order criterion follows by choosing a
sufficiently high coordinate in Proposition~\ref{prop:master}.  Three
familiar certificates are immediate:
\begin{equation}
u\in L^2(0,T_*;L^\infty),
\qquad
u\in L^\infty(0,T_*;L^3),
\qquad
\vort\in L^1(0,T_*;L^\infty).
\label{eq:familiar-certificates}
\end{equation}
Indeed, use respectively \(u\in L^2H^2\),
\(u\in C_tH_x^1\), and \(u\in L^2H^3\), followed by Sobolev embedding and
Cauchy--Schwarz in time.

\begin{corollary}[Finite-order continuation catalogue]
\label{cor:catalogue}
Every fixed finite-order classical readout in the left column is finite for
the reason in the right column.
\end{corollary}

\begin{center}
\small
\begin{tabularx}{\textwidth}{>{\raggedright\arraybackslash}p{0.32\textwidth}X}
\toprule
\textbf{Readout} & \textbf{Projection from \(\cI[u_0]\)} \\
\midrule
Serrin class
& \(u\in L^2_tH^2_x\hookrightarrow L^2_tL^\infty_x\), with
\(2/2+3/\infty=1\). \\
Critical endpoint
& \(u\in C_tH^1_x\hookrightarrow L^\infty_tL^3_x\). \\
Vorticity, strain, and Lipschitz control
& \(u\in L^2_tH^3_x\) gives
\(\vort,\strain,\nabla u\in L^2_tL^\infty_x\subset L^1_tL^\infty_x\). \\
Fixed-order dyadic shells
& For inhomogeneous blocks \(\Delta_j\), Bernstein and Cauchy--Schwarz give
\(\sum_j\int_0^{T_*}\norm{\Delta_j\vort}_{\infty}\dd t
\lesssim T_*^{1/2}\norm{u}_{L^2_tH^3_x}\). \\
Pressure and pressure gradient
& The Riesz formula \eqref{eq:pressure}, Sobolev products, and higher
coordinates give every finite mixed norm required for \(p\) and \(\nabla p\). \\
Type-I quantities
& Uniform finite-order bounds imply
\((T_*-t)^\gamma\norm{\nabla^ku(t)}_\infty\to0\) for each fixed
\(k\) and \(\gamma>0\). \\
Critical-height readout
& \(H(t)=\tfrac12\norm{\Lambda^{1/2}u(t)}_2^2\) is continuous and bounded;
its finite-time octave count is finite. \\
Ultraviolet tail
& For
\(H_{>K}(t)=\tfrac12\int_{|\xi|>K}|\xi|\,|\widehat u(t,\xi)|^2\dd\xi\),
higher uniform Sobolev control gives
\(\sup_{t\le T_*}H_{>K}(t)\to0\). \\
Partial-regularity readout
& The smooth representative supplied above has an empty singular set. \\
\bottomrule
\end{tabularx}
\end{center}

These are fixed-order, finite-horizon consequences.  A sum over every
Sobolev order also needs growth control, and infinite-horizon shell
integrability also needs decay.  Small-data thresholds, symmetry classes,
and vorticity-direction conditions keep their own assumptions.  The list is
not a second route: each entry is a finite projection of the one
datum-generated object that already reaches the endpoint.

